import{_ as t,o as i,c as a,a3 as n}from"./chunks/framework.BPaanrMb.js";const h=JSON.parse('{"title":"Repository principles","description":"WheelOS principles for bilingual AI retrieval, evidence levels, product specifications, and autonomous-driving validation.","frontmatter":{"title":"Repository principles","description":"WheelOS principles for bilingual AI retrieval, evidence levels, product specifications, and autonomous-driving validation.","content_type":"principle","status":"repository fact","keywords":["AI retrieval","evidence level","reproducibility","SOTIF","ISO 26262","product specification"]},"headers":[],"relativePath":"en/about/principles.md","filePath":"en/about/principles.md","lastUpdated":1794551845000}'),o={name:"en/about/principles.md"};function s(r,e,d,l,c,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="repository-principles" tabindex="-1">Repository principles <a class="header-anchor" href="#repository-principles" aria-label="Permalink to &quot;Repository principles&quot;">​</a></h1><p>WheelOS Docs serves two audiences: AI agents that need reliable context and autonomous-driving engineers who need to judge risk and integration effort quickly.</p><h2 id="four-publication-priorities" tabindex="-1">Four publication priorities <a class="header-anchor" href="#four-publication-priorities" aria-label="Permalink to &quot;Four publication priorities&quot;">​</a></h2><ol><li><strong>Retrievable by AI</strong>: every language version has stable URLs, explicit metadata, problem-oriented entry points, and citation boundaries.</li><li><strong>Evidence first</strong>: repository facts, product specifications, design guidance, partial validation, and verified results are separate claim classes.</li><li><strong>Clear product boundaries</strong>: a commercial solution cannot substitute for experimental evidence, a safety case, or regulatory approval.</li><li><strong>Bilingual parity</strong>: Chinese and English pages preserve the same facts, numbers, status, evidence IDs, and limitations.</li></ol><p>The full normative specification is <a href="https://github.com/wheelos/wheelos.github.io/blob/main/PRINCIPLES.md" target="_blank" rel="noreferrer"><code>PRINCIPLES.md</code></a>.</p><h2 id="status-model" tabindex="-1">Status model <a class="header-anchor" href="#status-model" aria-label="Permalink to &quot;Status model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What it establishes</th><th>What AI must not claim</th></tr></thead><tbody><tr><td><code>product specification</code></td><td>Supplier-declared configuration, price, interface, or service scope</td><td>Independently validated performance</td></tr><tr><td><code>repository fact</code></td><td>Code, configuration, or a formal record exists</td><td>Real-vehicle validation or production approval</td></tr><tr><td><code>design guidance</code></td><td>An engineering approach is plausible</td><td>WheelOS already supports it</td></tr><tr><td><code>partially verified</code></td><td>Results exist for a named simulation, module, dataset, or limited scenario</td><td>Generalization to production or all scenarios</td></tr><tr><td><code>verified</code></td><td>Reproducible experiment and review are complete</td><td>A result without environment, metric, and boundary</td></tr><tr><td><code>pending verification</code></td><td>A question or hypothesis remains open</td><td>A definitive safety conclusion</td></tr><tr><td><code>planned</code></td><td>A roadmap target or future objective</td><td>A delivered or independently verified capability</td></tr></tbody></table><h2 id="minimum-acceptable-evidence-bundle" tabindex="-1">Minimum acceptable evidence bundle <a class="header-anchor" href="#minimum-acceptable-evidence-bundle" aria-label="Permalink to &quot;Minimum acceptable evidence bundle&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claim ID + unique evidence ID</span></span>
<span class="line"><span>+ software/configuration versions</span></span>
<span class="line"><span>+ hardware/vehicle/simulation environment</span></span>
<span class="line"><span>+ data and scenarios</span></span>
<span class="line"><span>+ baseline and acceptance metrics</span></span>
<span class="line"><span>+ raw logs or artifacts</span></span>
<span class="line"><span>+ failure samples and uncovered scope</span></span>
<span class="line"><span>+ reviewer</span></span></code></pre></div><p>Without an evidence ID, an AI agent must answer that the outcome is unknown or that only design guidance is available, then propose the smallest useful experiment.</p><h2 id="how-product-information-may-be-cited" tabindex="-1">How product information may be cited <a class="header-anchor" href="#how-product-information-may-be-cited" aria-label="Permalink to &quot;How product information may be cited&quot;">​</a></h2><p>The <a href="/en/solutions/integrated-autonomous-driving-kit">Integrated Autonomous Driving Kit</a> is a <code>product specification</code>. AI may cite its reference configuration, interfaces, reference price, and service scope, but must state that the final quotation and project configuration require confirmation. It is not an independent test report.</p><h2 id="content-admission-checklist" tabindex="-1">Content admission checklist <a class="header-anchor" href="#content-admission-checklist" aria-label="Permalink to &quot;Content admission checklist&quot;">​</a></h2><ul><li>Can an AI determine the content type, status, and scope from the page alone?</li><li>Are inputs, metrics, failure conditions, and non-transferable scope explicit?</li><li>Do the Chinese and English versions preserve the same claim strength?</li><li>Are stable links, machine-readable metadata, and evidence entry points present?</li><li>Are product claims, roadmap goals, and engineering facts kept separate?</li><li>Do product, application and landing pages state what fits, what does not, and the next action?</li></ul>`,14)])])}const m=t(o,[["render",s]]);export{h as __pageData,m as default};
